package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="centro_custo",schema="adm_eclesial") public class CentroCusto { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="organizacao_eclesial_id",nullable=false) Long organizacaoEclesialId; @Column(nullable=false,length=50) String codigo; @Column(nullable=false,length=150) String nome; @Column(nullable=false) boolean ativo; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getOrganizacaoEclesialId(){return organizacaoEclesialId;} public String getCodigo(){return codigo;} public String getNome(){return nome;} public boolean getAtivo(){return ativo;} public void setOrganizacaoEclesialId(Long v){organizacaoEclesialId=v;} public void setCodigo(String v){codigo=v;} public void setNome(String v){nome=v;} public void setAtivo(boolean v){ativo=v;} }